"""Action extraction and limited uncertainty; not combat accuracy."""
import subprocess,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PRE="const assert=require('node:assert/strict'),E=require('./web_r4/loading-engine.js'),C=require('./web_r4/loading-coach.js'),c=require('./web_r4/loading-data.json');function run(i=0,s={},risk='BALANCED',period='LEVEL1'){let x=E.exampleInput(c,i);x.schema_version='lol-coach-loading-input-v4';x.preferences={risk};x.scenario={standard:'lane-standard-v1',overrides:s};x.planning={basis:'loading-plan-example-v1',overrides:{}};const r=E.analyze(x,c);r.coach=C.evaluate(r,c,r.input.scenario,period);return r;}"
class ActionBriefTests(unittest.TestCase):
 def node(self,body):
  r=subprocess.run(['node','-e',PRE+body],cwd=ROOT,capture_output=True,text=True);self.assertEqual(r.returncode,0,r.stderr[-4000:])
 def test_five_actions_each_refer_to_same_result_and_have_conditions_and_provenance(self):
  self.node("const r=run(),b=r.coach.planboard,a=b.action_summaries;assert(a,'missing action summaries');for(const area of ['lane','operations','fight']){assert.equal(a[area].items.length,5);assert.equal(new Set(a[area].items.map(v=>v.kind)).size,5);for(const v of a[area].items){assert(v.text&&v.detail_target&&v.source_paths.length);assert(v.conditions.length);assert(v.judgment.kind);assert(v.rule_ids.length);assert(!v.text.match(/수급|처리/));assert.equal(v.observation,false);}}assert(a.lane.items[1].source_paths.includes('wave.handling'));assert(a.operations.items[4].source_paths.includes('operations.fallback'));assert(a.fight.items[2].source_paths.includes('fight.target'));assert.equal(a.origin,'ANALYSIS_ASSUMPTIONS_NOT_OBSERVATION');")
 def test_uncertainty_does_not_erase_known_actions_or_change_unknown_to_tie(self):
  self.node("const a=run(),e=run(1),b=run(2,{},'BALANCED','LEVEL3_5'),u=run(1);assert.equal(a.coach.planboard.action_summaries.lane.judgment.kind,'CLEAR_IN_SCOPE');assert.equal(e.coach.planboard.action_summaries.lane.judgment.kind,'EXECUTION_DEPENDENT');assert.equal(b.coach.planboard.action_summaries.lane.judgment.kind,'CONDITION_DEPENDENT');const x=E.exampleInput(c,1);x.enemies.find(p=>p.position==='TOP').champion='Garen';const d=E.analyze(x,c);assert.equal(d.coach.planboard.action_summaries.lane.judgment.kind,'KNOWLEDGE_GAP');assert(d.coach.planboard.action_summaries.lane.items.some(v=>v.text.includes('미니언')||v.text.includes('경험치')));for(const r of [e,b,d]){assert.equal(r.coach.selected.metrics.ALLIN.assessment,'INSUFFICIENT');assert.equal(r.coach.planboard.fight.kill,'UNDETERMINED');}assert(e.coach.planboard.action_summaries.lane.items.some(v=>v.text.includes('급소')||v.text.includes('피오라')));")
 def test_conditions_and_roles_change_relevant_actions_but_risk_never_rewrites_assessments(self):
  self.node("const a=run(),b=run(0,{wave:'UNDER_TOWER'});assert.notEqual(a.coach.planboard.action_summaries.lane.items[1].text,b.coach.planboard.action_summaries.lane.items[1].text);const f=run(1);assert.notDeepEqual(a.coach.planboard.action_summaries.operations,f.coach.planboard.action_summaries.operations);assert.notEqual(a.coach.planboard.action_summaries.fight.items[1].text,f.coach.planboard.action_summaries.fight.items[1].text);const lo=run(0,{},'LOSS_LIMIT'),hi=run(0,{},'OPPORTUNITY');assert.deepEqual(lo.coach.periods,hi.coach.periods);assert.deepEqual(lo.coach.planboard.action_summaries.lane.judgment,hi.coach.planboard.action_summaries.lane.judgment);assert.equal(run(0,{resources:'LOW'}).coach.planboard.action_summaries.lane.judgment.outcome,'UNDETERMINED');")
 def test_action_text_is_extracted_from_live_report_not_example_table(self):
  self.node("const P=require('./web_r4/loading-planboard.js'),r=run(),b=structuredClone(r.coach.planboard);assert.equal(typeof P.actionSummaries,'function');b.wave.handling='이 웨이브의 막타만 칩니다. 다음 설명은 상세에 둡니다.';const a=P.actionSummaries(b,r.coach,r);assert.equal(a.lane.items[1].text,'이 웨이브의 막타만 칩니다.');assert.equal(a.lane.items[1].source_paths[0],'wave.handling');")
 def test_threat_summary_uses_actual_candidates_and_correct_phase_and_fallback_source(self):
  self.node("const P=require('./web_r4/loading-planboard.js'),r=run(1),b=r.coach.planboard;const t=b.action_summaries.fight.items.find(v=>v.kind==='THREAT');assert(t.threat_ids.includes('Malphite:R'));assert.equal(t.applicability.phase,'POST_LANE_LEARNED_KIT');assert.equal(t.applicability.lane_reference_period,'LEVEL1');assert(!('period' in t.applicability));assert(t.conditions.some(s=>s.includes('6レベル')||s.includes('6레벨')));assert.equal(b.action_summaries.fight.items[0].detail_target,'fight-methods');const z=run(),copy=structuredClone(z.coach.planboard);copy.fight.threats=copy.fight.threats.filter(v=>['LeeSin','Zed'].includes(v.champion));const actual=P.actionSummaries(copy,z.coach,z).fight.items.find(v=>v.kind==='THREAT');assert(actual.threat_ids.length);assert(actual.source_paths.includes('fight.awareness.danger'));assert.equal(actual.text,copy.fight.awareness.danger);copy.fight.threats=[];const fallback=P.actionSummaries(copy,z.coach,z).fight.items.find(v=>v.kind==='THREAT');assert.deepEqual(fallback.source_paths,['fight.stop']);assert.equal(fallback.detail_target,'fight-plan');assert.equal(fallback.threat_ids.length,0);")
if __name__=='__main__':unittest.main()
